/// `Softmax` (Softmax, reads `f3_Gemm`): TFLite's int16 softmax over 4 logits, output on the 2^-15 grid.
static SOFTMAX8: QSoftmax = QSoftmax {
    input_multiplier: 1543708202,
    input_shift: 1,
};

/// Run the network on an int16 input in the `INPUT` grid.
pub fn forward(input: &Input) -> Output {
    let mut b0 = [[[0i16; 6]; 5]; 8];
    let mut b1 = [[[0i16; 4]; 5]; 8];
    let mut b2 = [[[0i16; 5]; 2]; 3];
    CONV0.forward(input, &mut b0);
    CONV1.forward(&b0, &mut b1);
    CONV2.forward(&b1, &mut b2);
    let v3 = FC3.forward(
        b2.as_flattened()
            .as_flattened()
            .first_chunk::<30>()
            .expect("30 values"),
    );
    let v4 = v3.map(|x| apply_lut(x, &TANH4_LUT));
    let v5 = FC5.forward(&v4);
    let v6 = v5.map(|x| apply_lut(x, &SIGMOID6_LUT));
    let v7 = FC7.forward(&v6);
    let mut v8 = [0i16; 4];
    SOFTMAX8.forward(&v7, &mut v8);
    v8
}
